  splitStatCode: "",
  splitAmount: "",
  invoiceNumber: "",
  invoiceYear: "",
  splitAmountCurrency: "",
  isNew: true,
});

const isRegulatoryDetailEmpty = (detail = {}) =>
  isBlankText(detail?.splitStatCode) &&
  isBlankText(detail?.splitAmount) &&
  isBlankText(detail?.invoiceNumber) &&
