import rs.unicredit.cbr.repository.CbrValidationMatrixRepository;
import rs.unicredit.cbr.repository.CbrValidationMatrixLogRepository;

@Service
@RequiredArgsConstructor
public class ManualValidationErrorsService {

    private static final String VALIDATION_SCHEMA_NOT_FOUND_CODE = "VALIDATION_SCHEMA_NOT_FOUND";
    private static final String VALIDATION_SCHEMA_NOT_FOUND_MESSAGE = "Nije pronadjena validaciona sema";
    private static final TypeReference<List<ValidationApplyResult>> VALIDATION_RESULT_LIST_TYPE =
            new TypeReference<>() {
            };

    private final CbrTransactionRequestRepository requestRepository;
    private final CbrTransactionRepository transactionRepository;
    private final CbrValidationMatrixRepository validationMatrixRepository;
    private final CbrValidationMatrixLogRepository validationMatrixLogRepository;
    private final CbrStpValidationLogRepository stpValidationLogRepository;
    private final ObjectMapper objectMapper;

    public Optional<ManualValidationErrorsResponse> getByRequestId(Long requestId) {
        if (requestId == null) {
            return Optional.empty();
        }
        Optional<CbrTransactionRequest> requestOptional = requestRepository.findById(requestId);
        if (requestOptional.isEmpty()) {
            return Optional.empty();
        }
        CbrTransactionRequest request = requestOptional.get();
        CbrTransaction transaction = transactionRepository.findWithRegulatoryDetailsByRequestId(requestId)
                .orElse(null);
        List<ManualValidationErrorItem> errors = new ArrayList<>();
        String matrixSuccess = null;

        Optional<rs.unicredit.cbr.model.CbrValidationMatrixLog> matrixLog =
                validationMatrixLogRepository.findFirstByRequestIdOrderByRunNoDesc(requestId);
        if (matrixLog.isPresent()) {
            matrixSuccess = matrixLog.get().getSuccess();
            appendMatrixErrors(errors, matrixLog.get().getValidationResultJson(), transaction);
        }

        Optional<rs.unicredit.cbr.model.CbrStpValidationLog> stpLog =
                stpValidationLogRepository.findFirstByRequestIdOrderByExecutedAtDescIdDesc(requestId);
        if (stpLog.isPresent()) {
            appendStpErrors(errors, stpLog.get().getStpResultJson());
        }

        if (!isBlank(request.getErrorMessage())) {
            errors.add(ManualValidationErrorItem.builder()
                    .source("TECHNICAL")
                    .type("TECH_ERROR")
                    .validationNo(null)
                    .code("REQUEST_ERROR")
                    .message(request.getErrorMessage())
                    .build());
        }

        return Optional.of(ManualValidationErrorsResponse.builder()
                .requestId(requestId)
                .status(request.getStatus())
                .matrixSuccess(matrixSuccess)
                .errors(errors)
                .build());
    }

    private void appendMatrixErrors(List<ManualValidationErrorItem> errors, String json, CbrTransaction transaction) {
        if (isBlank(json)) {
            return;
        }
        try {
            List<ValidationApplyResult> results = objectMapper.readValue(json, VALIDATION_RESULT_LIST_TYPE);
            Map<BigDecimal, CbrValidationMatrix> matrixRulesByValidationNo = validationMatrixRepository
                    .findAllByOrderByValidationNoAsc()
                    .stream()
                    .filter(rule -> rule != null && rule.getValidationNo() != null)
                    .collect(Collectors.toMap(
                            rule -> normalizeValidationNo(rule.getValidationNo()),
                            rule -> rule,
                            (left, right) -> left,
                            LinkedHashMap::new));
            boolean hasMatchedMatrixRule = hasMatchedMatrixRule(results, transaction, matrixRulesByValidationNo);

            for (ValidationApplyResult result : results) {
                if (result == null || result.getFailedConditions() == null || result.getFailedConditions().isEmpty()) {
                    continue;
                }

                if (shouldSkipMatrixResult(result, transaction, matrixRulesByValidationNo)) {
                    continue;
                }

                String type = isPostMatrixValidationNo(result.getValidationNo()) ? "POST_MATRIX" : "MATRIX_RULE";
                for (String failed : result.getFailedConditions()) {
                    ManualValidationErrorItem errorItem = ManualValidationErrorItem.builder()
                            .source("MATRIX")
                            .type(type)
                            .validationNo(result.getValidationNo())
                            .code(failed)
                            .message(failed)
                            .build();
                    if (!"MATRIX_RULE".equals(type)) {
                        errors.add(errorItem);
                    }
                }
            }

            if (!hasMatchedMatrixRule) {
                errors.add(ManualValidationErrorItem.builder()
                        .source("MATRIX")
                        .type("MATRIX_RULE")
                        .validationNo(null)
                        .code(VALIDATION_SCHEMA_NOT_FOUND_CODE)
                        .message(VALIDATION_SCHEMA_NOT_FOUND_MESSAGE)
                        .build());
            }
        } catch (Exception ex) {
            errors.add(ManualValidationErrorItem.builder()
                    .source("TECHNICAL")
                    .type("TECH_ERROR")
                    .validationNo(null)
                    .code("MATRIX_LOG_PARSE")
                    .message("Failed to parse matrix validation log JSON: " + ex.getMessage())
                    .build());
        }
    }

    private boolean hasMatchedMatrixRule(
            List<ValidationApplyResult> results,
            CbrTransaction transaction,
            Map<BigDecimal, CbrValidationMatrix> matrixRulesByValidationNo) {
        if (results == null || results.isEmpty()) {
            return false;
        }
        return results.stream()
                .filter(result -> result != null && !isPostMatrixValidationNo(result.getValidationNo()))
                .filter(result -> !shouldSkipMatrixResult(result, transaction, matrixRulesByValidationNo))
                .anyMatch(ValidationApplyResult::isMatched);
    }

    private boolean shouldSkipMatrixResult(
            ValidationApplyResult result,
            CbrTransaction transaction,
            Map<BigDecimal, CbrValidationMatrix> matrixRulesByValidationNo) {
        if (result == null) {
            return false;
        }
        if (isPostMatrixValidationNo(result.getValidationNo())) {
            return false;
        }
        if (result.getValidationNo() == null || transaction == null || matrixRulesByValidationNo == null
                || matrixRulesByValidationNo.isEmpty()) {
            return false;
        }

        CbrValidationMatrix rule = matrixRulesByValidationNo.get(normalizeValidationNo(result.getValidationNo()));
        if (rule == null) {
            return false;
        }

        String messageType = transaction.getMessageType() == null ? null : normalize(transaction.getMessageType().name());
        String direction = transaction.getDirection() == null ? null : normalize(transaction.getDirection().name());

        return !(matches(rule.getCondMessageType(), messageType)
                && matches(rule.getCondDirection(), direction));
    }

    private BigDecimal normalizeValidationNo(BigDecimal value) {
        if (value == null) {
            return null;
        }
        return value.stripTrailingZeros();
    }

    private boolean matches(String condition, String actual) {
        if (isBlank(condition)) {
            return true;
        }
        String trimmed = condition.trim();
        if (trimmed.startsWith("<>")) {
            String expected = normalize(trimmed.substring(2));
            return actual != null && !actual.equals(expected);
        }
        if (trimmed.startsWith("=")) {
            String expected = normalize(trimmed.substring(1));
            return actual != null && actual.equals(expected);
        }
        String expected = normalize(trimmed);
        return actual != null && actual.equals(expected);
    }

    private String normalize(String value) {
        if (isBlank(value)) {
            return null;
        }
        return value.trim().toUpperCase();
    }

    private void appendStpErrors(List<ManualValidationErrorItem> errors, String json) {
        if (isBlank(json)) {
            return;
        }
        try {
            StpManualCheckResponse stpResult = objectMapper.readValue(json, StpManualCheckResponse.class);
            if (stpResult.getFailures() == null) {
                return;
            }
            for (StpFailure failure : stpResult.getFailures()) {
                if (failure == null) {
                    continue;
                }
                errors.add(ManualValidationErrorItem.builder()
                        .source("STP")
                        .type("STP_RULE")
                        .validationNo(null)
                        .code(failure.getCode())
                        .message(failure.getMessage())
                        .build());
            }
        } catch (Exception ex) {
            errors.add(ManualValidationErrorItem.builder()
                    .source("TECHNICAL")
                    .type("TECH_ERROR")
                    .validationNo(null)
                    .code("STP_LOG_PARSE")
                    .message("Failed to parse STP validation log JSON: " + ex.getMessage())
                    .build());
        }
    }

    private boolean isPostMatrixValidationNo(BigDecimal validationNo) {
        if (validationNo == null) {
            return false;
        }
        BigDecimal normalized = validationNo.stripTrailingZeros();
        if (normalized.scale() > 0) {
            return false;
        }
        return normalized.compareTo(BigDecimal.ONE) >= 0
                && normalized.compareTo(BigDecimal.valueOf(15L)) <= 0;
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }
}

