import React from "react";
import { CopyOutlined } from "@ant-design/icons";
import styles from "./Drawer.module.css";

const EMPTY_VALUE = "-";

const isPresent = (value) => value !== null && value !== undefined && value !== "";

const asText = (value) => (isPresent(value) ? String(value) : EMPTY_VALUE);

const formatDate = (value) => {
  if (!value) return EMPTY_VALUE;

  const parsedDate = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(parsedDate.getTime())) return String(value);

  const day = String(parsedDate.getDate()).padStart(2, "0");
  const month = String(parsedDate.getMonth() + 1).padStart(2, "0");
  const year = parsedDate.getFullYear();
  return `${day}.${month}.${year}`;
};

const formatAddress = (...parts) => {
  const formatted = parts
    .map((part) => (isPresent(part) ? String(part).trim() : ""))
    .filter(Boolean);

  return formatted.length > 0 ? formatted.join(", ") : EMPTY_VALUE;
};

const formatSettlementAmount = (value, currency = "EUR") => {
  if (!isPresent(value)) return EMPTY_VALUE;

  const number = Number(value);
  if (Number.isNaN(number)) return asText(value);

  return `${currency} ${number.toLocaleString("sr-RS", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
};

const Information = ({ selectedOrder, rawOrder }) => {
  const handleCopyCoreId = async () => {
    const coreId =
      selectedOrder?.coreId ??
      rawOrder?.creditorCoreId ??
      rawOrder?.debtorCoreId;
    if (!isPresent(coreId) || !navigator?.clipboard?.writeText) return;

    try {
      await navigator.clipboard.writeText(String(coreId));
    } catch (error) {
      // Clipboard failures should not interrupt the drawer flow.
    }
  };

  return (
    <section className={`${styles.panel} ${styles.clientInfoPanel}`}>
      <h3 className={`${styles.panelTitle} ${styles.clientInfoTitle}`}>
        Klijentske informacije
      </h3>

      <div className={styles.debtorBlock}>
        <p className={`${styles.groupLabel} ${styles.debtorLabel}`}>DEBTOR</p>
        <div className={`${styles.detailsRows} ${styles.debtorRows}`}>
          <div className={`${styles.detailRow} ${styles.debtorNameIbanRow}`}>
            <span className={styles.detailLabel}>Name &amp; IBAN</span>
            <div className={`${styles.detailValueWrap} ${styles.debtorNameIbanValue}`}>
              <span className={`${styles.detailValueMain} ${styles.debtorNameText}`}>
                {asText(rawOrder?.debtorName)}
              </span>
              <span className={`${styles.detailValueSub} ${styles.debtorIbanText}`}>
                {asText(rawOrder?.debtorIban)}
              </span>
            </div>
          </div>

          <div className={styles.detailRow}>
            <span className={styles.detailLabel}>Core ID</span>
            <div className={styles.detailValueWrap}>
              <div className={styles.inlineValue}>
                <span className={styles.detailValueMain}>
                  {asText(
                    selectedOrder?.coreId ??
                      rawOrder?.creditorCoreId ??
                      rawOrder?.debtorCoreId
                  )}
                </span>
                <button
                  type="button"
                  className={styles.iconButton}
                  aria-label="Copy core id"
                  onClick={handleCopyCoreId}
                >
                  <CopyOutlined />
                </button>
              </div>
            </div>
          </div>

          <div className={styles.detailRow}>
            <span className={styles.detailLabel}>Adresa</span>
            <div className={styles.detailValueWrap}>
              <span className={styles.detailValueMain}>
                {asText(rawOrder?.debtorAddress ?? rawOrder?.debtorPostalAddress)}
              </span>
              <span className={styles.detailValueSub}>
                {formatAddress(rawOrder?.debtorTown, rawOrder?.debtorCountry)}
              </span>
            </div>
          </div>
        </div>
      </div>

      <p className={styles.groupLabel}>CREDITOR</p>
      <div className={styles.detailsRows}>
        <div className={styles.detailRow}>
          <span className={styles.detailLabel}>Name &amp; IBAN</span>
          <div className={styles.detailValueWrap}>
            <span className={styles.detailValueMain}>{asText(rawOrder?.creditorName)}</span>
            <span className={styles.detailValueSub}>{asText(rawOrder?.creditorIban)}</span>
          </div>
        </div>

        <div className={styles.detailRow}>
          <span className={styles.detailLabel}>Banka &amp; BIC</span>
          <div className={styles.detailValueWrap}>
            <span className={styles.detailValueMain}>{asText(rawOrder?.creditorAgent)}</span>
            <span className={styles.detailValueSub}>{asText(rawOrder?.creditorIdBic)}</span>
          </div>
        </div>

        <div className={styles.detailRow}>
          <span className={styles.detailLabel}>Adresa</span>
          <div className={styles.detailValueWrap}>
            <span className={styles.detailValueMain}>
              {asText(rawOrder?.creditorAddress ?? rawOrder?.creditorPostalAddress)}
            </span>
            <span className={styles.detailValueSub}>
              {formatAddress(rawOrder?.creditorTown, rawOrder?.creditorCountry)}
            </span>
          </div>
        </div>
      </div>

      <p className={styles.groupLabel}>SETTLEMENT</p>
      <div className={styles.detailsRows}>
        <div className={styles.detailRow}>
          <span className={styles.detailLabel}>Amount</span>
          <div className={styles.detailValueWrap}>
